import{_ as a,C as i,o as d,c as n,j as t,a as s,E as r,a3 as c}from"./chunks/framework.BJ2rlPXv.js";const f=JSON.parse('{"title":"Request Editor","description":"","frontmatter":{},"headers":[],"relativePath":"tui/request-editor.md","filePath":"tui/request-editor.md","lastUpdated":1795574373000}'),l={name:"tui/request-editor.md"};function h(p,e,u,k,g,m){const o=i("Screen");return d(),n("div",null,[e[0]||(e[0]=t("h1",{id:"request-editor",tabindex:"-1"},[s("Request Editor "),t("a",{class:"header-anchor",href:"#request-editor","aria-label":'Permalink to "Request Editor"'},"​")],-1)),e[1]||(e[1]=t("p",null,"Open a request from the list to enter the editor. It shows the request details across six tabs.",-1)),e[2]||(e[2]=t("h2",{id:"layout",tabindex:"-1"},[s("Layout "),t("a",{class:"header-anchor",href:"#layout","aria-label":'Permalink to "Layout"'},"​")],-1)),r(o,{name:"request-editor",caption:"The editor after alt+enter: request tabs on the left, the response on the right"}),e[3]||(e[3]=c(`<h2 id="top-controls" tabindex="-1">Top controls <a class="header-anchor" href="#top-controls" aria-label="Permalink to &quot;Top controls&quot;">​</a></h2><ul><li><strong>Method</strong> — select from GET, POST, PUT, PATCH, DELETE, OPTIONS, HEAD</li><li><strong>Server URL</strong> — picked from the spec&#39;s <code>servers</code> list</li><li><strong>URI</strong> — the endpoint path, with <code>{{env.X}}</code> support</li><li><strong>Send</strong> — press <code>Enter</code> on the Send button, or <code>alt+enter</code> from any field. The response, status/contract checks and test results appear on the right (<a href="./response-preview">Response View</a>)</li></ul><p>Opening an operation pre-fills path parameters, required query/header parameters and the request body from the spec&#39;s examples. Bodies can be edited in <code>$EDITOR</code> with <code>ctrl+x</code>.</p><p>When the spec declares a request body schema but no example, the editor builds one from the schema (examples, defaults, enums, formats and minimums of each property) so you start from a valid shape. <code>lazyapi run</code> never invents bodies: this only fills the editor.</p><h2 id="mouse-and-selects" tabindex="-1">Mouse and selects <a class="header-anchor" href="#mouse-and-selects" aria-label="Permalink to &quot;Mouse and selects&quot;">​</a></h2><p>Everything can be clicked: the method and server selects, the URI (places the cursor), <strong>Send</strong>, the tab labels, fields inside a tab (focuses them), the code editors (click places the cursor, drag selects, shift+click extends) and the response. The mouse wheel scrolls the tab under the pointer, an open list, or the response. In the request list, a click selects and a double click opens.</p><p>Selects show <code>▾</code>. <code>enter</code>/<code>space</code> or a click opens the list; <code>↑</code>/<code>↓</code>, <code>home</code>/<code>end</code>, <code>pgup</code>/<code>pgdown</code>, the wheel or typing the first letters (<code>p</code> → POST, <code>p</code> again → PATCH) move; <code>enter</code>, <code>tab</code> or a click picks; <code>esc</code> or a click outside cancels. Closed, <code>↑</code>/<code>↓</code> change the value directly.</p><h2 id="switching-rows-on-and-off" tabindex="-1">Switching rows on and off <a class="header-anchor" href="#switching-rows-on-and-off" aria-label="Permalink to &quot;Switching rows on and off&quot;">​</a></h2><p>Every header, query parameter, path parameter and form field has a checkbox (☑ on, ☐ off), and every auth scheme an <strong>on/off</strong> switch on its first line. <code>ctrl+t</code> on the focused row (or a click on the box) toggles it. A row that is off keeps its name and value but is not sent; auth schemes that are off are not applied.</p><p>The state is saved with the request&#39;s draft in <code>.lazyapi/.local/drafts/</code> (under <code>disabled:</code>, and <code>disabled: true</code> on auth schemes), so it survives restarts and is used by <code>s</code> in the list. Saving to the spec (<code>ctrl+o</code>) keeps the parameter and scheme definitions of rows that are off; <code>lazyapi run</code> reads the spec and is not affected.</p><h2 id="templates" tabindex="-1">Templates <a class="header-anchor" href="#templates" aria-label="Permalink to &quot;Templates&quot;">​</a></h2><p><code>{{env.NAME}}</code> and <code>{{var.NAME}}</code> work in every field and editor, and are colored as you type: teal when the active environment has a value, <strong>red underlined</strong> when it does not.</p><ul><li>Type <code>{{</code> or the shortcut <code>$</code> (<code>$TOK</code>) to open the completion menu: the env file&#39;s variables and the environment&#39;s vars, with values masked when they look like credentials. <code>↑</code>/<code>↓</code> choose, <code>tab</code> (or <code>enter</code>) inserts <code>{{env.TOKEN}}</code>, <code>esc</code> closes the menu.</li><li>References without a value are also listed in the bottom bar (<code>⚠ no value: {{env.TOKEN}}</code>), because they would be sent as empty strings. Vars set by scripts at run time (<code>vars.set</code>, <code>before()</code>) are not known before sending.</li><li>A password field shows its value when it is only references (<code>{{env.PASSWORD}}</code> holds no secret).</li><li>The URL field also colors the host, <code>{path}</code> parameters and query keys.</li></ul><h2 id="tabs" tabindex="-1">Tabs <a class="header-anchor" href="#tabs" aria-label="Permalink to &quot;Tabs&quot;">​</a></h2><h3 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h3><p>A free-form <strong>Summary</strong> (single line) and <strong>Description</strong> (multi-line) for the operation. These are persisted back to the OpenAPI spec on save.</p><h3 id="params" tabindex="-1">Params <a class="header-anchor" href="#params" aria-label="Permalink to &quot;Params&quot;">​</a></h3><p>Two sub-sections:</p><ul><li><strong>Query parameters</strong> — key/value pairs sent as URL query string. Add with <code>n</code> + <code>q</code>.</li><li><strong>Path parameters</strong> — key/value pairs that replace <code>{param}</code> placeholders in the URI. Add with <code>n</code> + <code>p</code>.</li></ul><h3 id="auth" tabindex="-1">Auth <a class="header-anchor" href="#auth" aria-label="Permalink to &quot;Auth&quot;">​</a></h3><p>Authentication schemes of the request. <code>ctrl+r</code> adds one, <code>⌫</code>/<code>del</code> on its <strong>Scheme</strong> select removes it. <strong>Scheme</strong> reuses a scheme the spec already defines (so several requests share one definition) or creates a new one. Supports:</p><ul><li><strong>Basic</strong> — Username + Password</li><li><strong>Bearer</strong> — Token</li><li><strong>API Key</strong> — Key name + In (header/query/cookie) + Value</li><li><strong>OAuth2</strong> — Grant, Client ID/secret, Authorization/Token URL, Scopes</li><li><strong>OpenID Connect</strong> — Issuer URL (endpoints discovered from <code>.well-known/openid-configuration</code>), Grant, Client ID/secret, Scopes</li></ul><p>OAuth schemes have a <strong>Login</strong> button (<code>ctrl+l</code>) and show the stored session. Sending without a session logs in first. See <a href="/v2/authentication">Authentication</a>.</p><h3 id="header" tabindex="-1">Header <a class="header-anchor" href="#header" aria-label="Permalink to &quot;Header&quot;">​</a></h3><p>Custom HTTP headers as key/value pairs. Add with <code>n</code> + <code>h</code>. Common headers like <code>Content-Type</code> are set automatically from the body type.</p><h3 id="body" tabindex="-1">Body <a class="header-anchor" href="#body" aria-label="Permalink to &quot;Body&quot;">​</a></h3><p>The request body, in the operation&#39;s media type:</p><ul><li><strong>JSON, text, XML, …</strong> — the code editor (below): JSON is colored, validated as you type (templates count as values) and formatted with <code>alt+f</code>. <code>ctrl+x</code> opens it in <code>$EDITOR</code>.</li><li><strong><code>application/x-www-form-urlencoded</code> and <code>multipart/form-data</code></strong> — <strong>Form fields</strong>: one name/value row per field, like the Headers tab. <code>tab</code> / <code>shift+tab</code> move between cells, <code>ctrl+g</code> adds a field, a row without a name is dropped, and a repeated name sends the field several times. The rows are kept as a JSON object, which is encoded as form fields when sending; <code>ctrl+x</code> edits that object in <code>$EDITOR</code>. File parts are only sent from the CLI (<code>--file</code>).</li></ul><p>Select the type from the dropdown.</p><h3 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h3><p>The code editor, in JavaScript, for the operation&#39;s test script (see <a href="./../scripting">Test Scripts</a>). Scripts can use <code>request</code>, <code>response</code>, <code>env</code>, <code>vars</code>, <code>lazyapi.send()</code>, <code>test()</code> and <code>expect()</code>, and may import relative files or <code>https://</code> modules.</p><p>Press <code>F5</code> to run the script against the last response. Results, failure messages and <code>console</code> output appear below the editor. When you save (<code>ctrl+o</code>), the script is written to <code>.lazyapi/tests/&lt;operationId&gt;.js</code> next to the spec and linked through <code>x-lazyapi-tests</code>.</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">test</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">(</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;">&quot;status is 200&quot;</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">,</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;"> ()</span><span style="--shiki-light:#8839EF;--shiki-dark:#CBA6F7;"> =&gt;</span><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;"> expect</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">(response)</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">.</span><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">toHaveStatus</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">(</span><span style="--shiki-light:#FE640B;--shiki-dark:#FAB387;">200</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">))</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">;</span></span>
<span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">test</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">(</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;">&quot;matches the OpenAPI schema&quot;</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">,</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;"> ()</span><span style="--shiki-light:#8839EF;--shiki-dark:#CBA6F7;"> =&gt;</span><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;"> expect</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">(response)</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">.</span><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">toMatchSchema</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">())</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">;</span></span>
<span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">test</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">(</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;">&quot;has an id&quot;</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">,</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;"> ()</span><span style="--shiki-light:#8839EF;--shiki-dark:#CBA6F7;"> =&gt;</span><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;"> expect</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">(response</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">.</span><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">json</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">())</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">.</span><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">toHaveProperty</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">(</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;">&quot;id&quot;</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">))</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">;</span></span></code></pre></div><h2 id="code-editor" tabindex="-1">Code editor <a class="header-anchor" href="#code-editor" aria-label="Permalink to &quot;Code editor&quot;">​</a></h2><p>Body, Tests and the Docs description use the same editor:</p><ul><li>syntax colors (Catppuccin), line numbers with the current line highlighted, and a status line with the language, <code>Ln, Col</code> and, for JSON, <code>✓ valid</code> or the parse error. The line with the error gets a red <code>●</code>;</li><li><code>{</code>, <code>[</code>, <code>(</code> and quotes close themselves; typing the closer steps over it; <code>backspace</code> between a pair removes both; <code>enter</code> keeps the indentation and opens an indented line between brackets;</li><li><code>tab</code> / <code>shift+tab</code> indent and dedent (two spaces);</li><li><code>alt+f</code> formats JSON (key order kept);</li><li><code>ctrl+z</code> / <code>ctrl+y</code> undo and redo; pasting keeps line breaks;</li><li><strong>selection</strong>: <code>shift</code> + any movement (arrows, <code>home</code>/<code>end</code>, <code>alt+←/→</code>, <code>pgup</code>/<code>pgdown</code>) selects, <code>alt+a</code> selects everything, <code>esc</code> clears it. Typing replaces the selection, and an opening bracket or quote wraps it; <code>tab</code> / <code>shift+tab</code> indent or dedent the selected lines; <code>backspace</code> deletes it;</li><li><strong>clipboard</strong>: <code>ctrl+c</code> copies the selection (with nothing selected it quits, as everywhere), <code>alt+x</code> cuts, <code>alt+v</code> pastes from the system clipboard (terminal paste works too);</li><li><code>home</code> goes to the indentation, then column 0; <code>ctrl+home</code> / <code>ctrl+end</code>; <code>alt+←</code> / <code>alt+→</code> move by word; <code>ctrl+w</code> deletes the word before the cursor; <code>ctrl+u</code> deletes to the line start;</li><li>in Tests, syntax errors as you type (JavaScript and TypeScript, checked with esbuild: the line gets a red <code>●</code>, the message goes to the status line) and the <strong>signature</strong> of the call the cursor is in (<code>ƒ lazyapi.send(target, options?)</code>, <code>toHaveProperty(path, value?)</code>, …);</li><li>dynamic values: <code>{{$</code> (or <code>$name</code>) offers the built-in faker variables and the helpers the Tests script exports, with a description; unknown names are drawn as missing and listed in the help bar;</li><li>in Tests, completions for the script API as you type: <code>response.</code> (<code>status</code>, <code>json()</code>, …), <code>expect(…).</code> (every matcher), <code>lazyapi.</code>, <code>env.</code>, <code>vars.</code> and the globals. Methods insert <code>()</code> with the cursor inside.</li></ul><p><code>esc</code> closes an open menu first, then leaves the editor.</p><h2 id="field-navigation" tabindex="-1">Field navigation <a class="header-anchor" href="#field-navigation" aria-label="Permalink to &quot;Field navigation&quot;">​</a></h2><ul><li><code>Tab</code> / <code>Shift+Tab</code> cycles through: Method → Server → URI → Send → Tabs → Response</li><li><code>Enter</code> inside a tab activates tab content (Blocker mode)</li><li><code>Esc</code> blurs tab content; a second <code>Esc</code> exits the tab back to field cycling</li><li>Within tab content (e.g., Params rows), Tab/Shift+Tab wraps cyclically</li></ul><h2 id="saving" tabindex="-1">Saving <a class="header-anchor" href="#saving" aria-label="Permalink to &quot;Saving&quot;">​</a></h2><ul><li><code>ctrl+o</code> — saves changes back to the spec (Summary, Description, param definitions, body content type, auth schemes, test script)</li><li><code>Ctrl+E</code> — saves the last response as an example in the spec</li><li>Runtime values (body content, header values, param values) are saved to session temp files</li></ul>`,41))])}const b=a(l,[["render",h]]);export{f as __pageData,b as default};
